interface ShippingStrategy {
  calculate(cart: Cart): number;
}

class FedExStrategy implements ShippingStrategy {
  calculate(cart: Cart) { return cart.weight * 1.5 + 5; }
}
class UPSStrategy implements ShippingStrategy {
  calculate(cart: Cart) { return cart.weight * 1.2 + 7; }
}

class ShippingCalculator {
  constructor(private strategy: ShippingStrategy) {}
  calculate(cart: Cart) { return this.strategy.calculate(cart); }
}

